import json
for n in ['current','tail','de_spx','spx1928']:
    d=json.load(open(f'scratch/overnight/results/{n}.json'))
    def walk(x,p=''):
        if isinstance(x,dict):
            for k,v in x.items(): walk(v,p+'.'+k)
        elif not isinstance(x,list): 
            if any(s in p for s in ['typical','loss','runaway','a1','percent']): print(n,p,x)
    walk(d)
" | grep -v "settings\.\(a2\|a3\|v1\)" | head -40

